//     ...
//     "valor": {
//     "original": "0.00",
//     "retirada": {
//     "saque": {
//     "valor": "5.00",
//     "modalidadeAlteracao": 1,
//     "modalidadeAgente": "AGFSS",
//     "prestadorDoServicoDeSaque": "12345678"
//     }
//     }
//     },
//     ...
//     ```
